def page_sections(items):
  result=''
  for ix,(title,body) in enumerate(items,1):
    result+=f'<section class="cms-entry reveal"><span class="cms-number">{ix:02}</span><div><h2>{title}</h2><p>{body}</p></div></section>'
  return result

def page_html(slug,rec):
  title,subtitle,eyebrow,lead,items,action,link=rec
  extra=''
  if slug=='how-to-install':
    extra='''<div class="cms-video-block reveal"><img src="/assets/img/install-guide-poster.jpg" alt="VELORI installation tutorial" loading="lazy"><div><span class="eyebrow eyebrow-light">STEP BY STEP</span><h2>Prefer to watch?</h2><p>Your 60-second guide is included here and in the home page popup.</p><button type="button" class="button button-white" data-video-open>▶ Play the walkthrough</button></div></div>'''
  if slug=='downloads':
    extra='''<div class="cms-qr-block reveal"><div><h2>Scan to download the APK</h2><p>This QR code points to the planned public APK URL and works after the owner has deployed the site to download.veloryz.online.</p><a href="/files/VELORI-Android.apk" class="button button-purple" download>Download APK ↓</a></div><img src="/assets/img/velori-download-qr.png" alt="QR code for VELORI Android APK download"></div>'''
  if slug=='faq':
    extra='''<div class="faq-search-group"><label for="faqSearch">Find an answer</label><input id="faqSearch" type="search" placeholder="Search these questions..." autocomplete="off"><p id="faqSearchEmpty" hidden>No matching questions found. Try a different word.</p></div>'''
  sectioncls=' cms-faq' if slug=='faq' else ''
  content=f'''<main id="main"><section class="cms-hero"><div class="cms-hero-deco" aria-hidden="true">✳</div><div class="shell"><a href="/" class="cms-back">← Back to download home</a><span class="eyebrow"><span class="micro-dot"></span> VELORI / {escape(eyebrow.upper())}</span><h1>{title}</h1><p>{subtitle}</p></div></section><section class="cms-content section-pad"><div class="shell cms-layout"><aside class="cms-aside"><span class="cms-aside-label">ON THIS PAGE</span><div class="cms-aside-sticky"><div class="cms-icon"><img src="/assets/img/velori-logo.png" alt=""></div><p>Official VELORI download center</p><span class="cms-updated">UPDATED OCTOBER 2026</span><a href="/files/VELORI-Android.apk" download>↓ Download APK</a><button data-video-open type="button">▶ Watch guide</button></div></aside><div class="cms-main{sectioncls}"><div class="cms-lead reveal"><p>{lead}</p></div>{extra}<div class="cms-entries">{page_sections(items)}</div><div class="cms-next reveal"><div><span>KEEP EXPLORING</span><h3>Want to go a little further?</h3></div><a class="button button-purple" href="{link}" {'download' if link.endswith('.apk') else ''} {'data-video-open' if link=='#video' else ''}>{action} ↗</a></div><div class="cms-legal-note">This page is informational. Verify final policy, business details, and product capabilities before public launch.</div></div></div></section></main>'''
  return content

def shell(body,title,desc,path):
  canonical=SITE+path
  return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#faf9fd"><meta name="description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:site_name" content="VELORI Download"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:image" content="{SITE}/assets/img/velori-logo.png"><meta property="og:url" content="{canonical}"><link rel="canonical" href="{canonical}"><link rel="icon" type="image/png" href="/assets/img/favicon.png"><link rel="manifest" href="/manifest.webmanifest"><meta name="color-scheme" content="light dark"><title>{escape(title)} | VELORI by VELORYZ</title><link rel="stylesheet" href="/assets/css/site.css"></head><body><a href="#main" class="skip-link">Skip to main content</a>{header}{body}{footer}</body></html>'''

